edits.new:
reg [3:0] hint_needed;
reg [3:0] hint_needed_r;
reg [3:0] K;

edits.old:
poly0_i <= poly0_ie;
poly1_i <= poly1_ie;
poly_valid_i <= (rst) ? 0 : poly_valid_ie;

edits.new:
poly0_i <= poly0_ie;
poly1_i <= poly1_ie;
poly_valid_i <= (rst) ? 0 : poly_valid_ie;
for (i = 0; i < 4; i = i + 1)
    hint_needed_r[i] <= !(poly0_ie[24*i+:24] <= ((sec_lvl == 2) ? GAMMA2_2 : GAMMA2_35) || poly0_ie[24*i+:24] > Q-((sec_lvl == 2) ? GAMMA2_2 : GAMMA2_35)) || (poly0_ie[24*i+:24] == Q-((sec_lvl == 2) ? GAMMA2_2 : GAMMA2_35) && poly1_ie[24*i+:24] != 0);

edits.old:
reg [63:0] dout_buffer;
reg [511:0] MU_SIPO;
reg [512 - 1 : 0] C_SIPO;
reg [63:0] SIGN;
reg [1:0] C_POLY [255:0];

edits.new:
reg [63:0] dout_buffer;
reg [511:0] MU_SIPO;
reg [512 - 1 : 0] C_SIPO;
reg [63:0] SIGN;
reg [1:0] C_POLY [255:0];
reg sample_addr_le_sample_no;

edits.old:
S_SAMPLEC: begin
    if (sample_no <= 255) begin
        ctr <= ctr_next;
        if (sample_addr <= sample_no) begin
            // ACCEPT
            sample_no <= sample_no + 1;
            C_POLY[sample_no]   <= C_POLY[sample_addr];
            C_POLY[sample_addr] <= (SIGN[0]) ? 2 : 1; // 2 -> -1
            SIGN                <= (SIGN >> 1);
        end
    end else begin
        ctr <= 0;
    end
end

edits.new:
S_SAMPLEC: begin
    // precompute flag for next cycle: compare next sample_addr against next sample_no
    sample_addr_le_sample_no <= (dout[{4'd7-(ctr_next[2:0]),3'd0}+:8] <= (sample_no + 1));
    if (sample_no <= 255) begin
        ctr <= ctr_next;
        if (sample_addr_le_sample_no) begin
            // ACCEPT
            sample_no <= sample_no + 1;
            C_POLY[sample_no]   <= C_POLY[sample_addr];
            C_POLY[sample_addr] <= (SIGN[0]) ? 2 : 1; // 2 -> -1
            SIGN                <= (SIGN >> 1);
        end
    end else begin
        ctr <= 0;
    end
end

reg [2*W-1:0] di_shift;

reg [5:0] ENCODE_LVL;
reg [5:0] ENCODE_LVL_reg;

edits.old:
always @(*) begin    
    ETA = 0;

    /* ----- decoder lane connection ----- */
    ENCODE_LVL = 0;

edits.new:
always @(posedge clk) begin
    case ({sec_lvl, encode_modei})
    {3'bX??, ENCODE_T0}: ENCODE_LVL_reg <= 13;
    {3'bX??, ENCODE_T1}: ENCODE_LVL_reg <= 10;
    {3'd2, ENCODE_S2}, {3'd5, ENCODE_S2},
    {3'd2, ENCODE_S1}, {3'd5, ENCODE_S1}: ENCODE_LVL_reg <= 3;
    {3'd3, ENCODE_S2}, {3'd3, ENCODE_S1}: ENCODE_LVL_reg <= 4;
    {3'd3, ENCODE_W1}, {3'd5, ENCODE_W1}: ENCODE_LVL_reg <= 4;
    {3'd2, ENCODE_W1}: ENCODE_LVL_reg <= 6;
    {3'd2, ENCODE_Z}: ENCODE_LVL_reg <= 18;
    {3'd3, ENCODE_Z}, {3'd5, ENCODE_Z}: ENCODE_LVL_reg <= 20;
    default: ENCODE_LVL_reg <= 0;
    endcase
end

always @(*) begin    
    ETA = 0;

    /* ----- decoder lane connection ----- */
    ENCODE_LVL = ENCODE_LVL_reg;

edits.old:
EXPAND_HINT: begin
    hint_poly[next_hint+hint_offset] <= 1;
    state <= (ctr+1 >= hint_cnt[K-1]) ? APPLY_HINT : EXPAND_HINT;
end

edits.new:
EXPAND_HINT: begin
    hint_poly[next_hint+hint_offset] <= 1;
    expand_done_flag <= (ctr_next + 1 >= hint_cnt[K-1]);
    state <= expand_done_flag ? APPLY_HINT : EXPAND_HINT;
end
